// Facebook Messenger webhook -> unified runtime item(s)
// Token/page config is NOT hardcoded here.
// Next step must lookup public.social_pages by provider='facebook' and external_id=fb_page_id.

const req = $json;
const body = req.body ?? req;
const results = [];

for (const entry of (Array.isArray(body.entry) ? body.entry : [])) {
  const pageId = String(entry.id || "").trim();

  for (const ev of (Array.isArray(entry.messaging) ? entry.messaging : [])) {
    if (!ev.message) continue;
    if (ev.message.is_echo) continue;

    const senderId = String(ev.sender?.id || "").trim();
    const mid = String(ev.message?.mid || "").trim();
    const text = String(ev.message?.text || "").trim();

    let messageType = "text";
    let mediaUrl = null;

    if (Array.isArray(ev.message.attachments) && ev.message.attachments.length > 0) {
      const att = ev.message.attachments[0];
      messageType = String(att.type || "attachment").toLowerCase();
      mediaUrl = att.payload?.url || null;
    }

    results.push({
      json: {
        platform: "facebook",
        fb_page_id: pageId,
        channel_platform_id: pageId,

        fb_recipient_id: senderId,
        platform_user_id: senderId,
        line_user_id: senderId,
        reply_token: "",

        event_type: "message",
        message_type: messageType,
        text: text || (mediaUrl ? "[สื่อ/รูปภาพ]" : ""),
        cmd: null,
        ts: ev.timestamp || Date.now(),

        account_key: `FB:${pageId || "unknown_page"}`,
        page_access_token: "",
        ADMIN_TO: "",
        LIFF_BOOK_URL: "",
        INBOX_BASE_URL: "https://admin.paaair.online/webhook/line/chat",

        platform_message_id: mid || null,
        raw_event: {
          platform: "facebook",
          page_id: pageId,
          sender: ev.sender,
          recipient: ev.recipient,
          timestamp: ev.timestamp,
          message: ev.message,
          media_url: mediaUrl
        }
      }
    });
  }
}

if (!results.length) {
  return [{
    json: {
      platform: "facebook",
      event_type: "skip",
      message_type: "none",
      text: "",
      skip_reason: "no_customer_message",
      raw_event: body
    }
  }];
}

return results;

const brain = $json.brain_response || {};
const adminSummary = brain.admin_summary || {};
const isAdminTakeover = brain.recommended_action === 'skip_reply' && brain.decision_meta?.reason === 'admin_takeover_active';

return [{
  json: {
    request_id: `n8n_line_handoff_${Date.now()}_${$execution.id}`,
    source: isAdminTakeover ? `${String($json.platform || 'line')}_fix_skip_reply` : `${String($json.platform || 'line')}_fix_reply_handoff`,
    channel: String($json.platform || 'line'),
    channel_user_id: $json.platform_user_id || $json.line_user_id || null,
    message_id: $json.raw_event?.message?.id || null,
    customer_message: String($json.text || ''),
    intent: brain.intent || 'admin_handoff',
    confidence: typeof brain.confidence === 'number' ? brain.confidence : 1,
    reason: isAdminTakeover ? 'HUMAN_OWNED_BLOCK' : 'handoff_required',
    summary: adminSummary.summary || (isAdminTakeover ? 'AI silent (Handover Active)' : 'AI replied to customer and requested admin follow-up'),
    recommended_next_action: adminSummary.recommended_next_action || (isAdminTakeover ? 'wait_for_admin_followup' : 'admin_review_and_contact'),
    extracted_fields: brain.extracted_fields || {},
    missing_fields: Array.isArray(brain.missing_fields) ? brain.missing_fields : [],
    received_at: new Date().toISOString()
  }
}];

// Resolve OA by LINE webhook "destination"
const body = $json.body ?? $json;
const dest = String(body?.destination || '').trim();

// map destination -> account_key + channel_platform_id
// OA3 (PA Cool): update channel_platform_id to the real LINE channel ID once known
const DEST_TO = {
  "U7ca0e85474df0c18189cd593a5d469c1": { account_key: "PAA Air",  channel_platform_id: "2007958198" }, // OA1
  "Ue0329c8bb058d3f3014b856a8b3c3dce": { account_key: "P&A Air",  channel_platform_id: "2007779665" }, // OA2
  "U1eee2ec37e5f71c20f38dd52154f6ad7": { account_key: "PA Cool",  channel_platform_id: "2008387791" },    // OA3 - replace PA_COOL with real channel ID
};

const m = DEST_TO[dest];
if (!m) {
  return [{ json: { ok: false, error: "unknown_destination", destination: dest, body } }];
}

return [{
  json: {
    ...$json,
    account_key: m.account_key,
    channel_platform_id: m.channel_platform_id,
  }
}];

// Explode LINE body.events[] -> 1 item per event
const req = $json;
const body = req.body ?? req;
const events = Array.isArray(body?.events) ? body.events : [];

return events.map((event) => {
  const event_type = String(event?.type || '').toLowerCase();
  const message_type = String(event?.message?.type || '').toLowerCase();
  const line_user_id = event?.source?.userId || null;
  const reply_token = event?.replyToken || "";
  const text = message_type === 'text' ? String(event?.message?.text || '').trim() : '';
  const postback_data = event_type === 'postback' ? String(event?.postback?.data || '').trim() : '';
  const cmd = String(postback_data || text || '').trim();

  return {
    json: {
      account_key: req.account_key,
      channel_platform_id: req.channel_platform_id,
      event_type,
      message_type,
      line_user_id,
      reply_token,
      text,
      postback_data,
      cmd,
      ts: event?.timestamp || null,
      raw_event: {
        type: event?.type,
        mode: event?.mode,
        source: event?.source,
        timestamp: event?.timestamp,
        message: event?.message,
        postback: event?.postback,
      }
    }
  };
});

const LIFF = String($json.LIFF_BOOK_URL || '').trim();
const replyToken = String($json.reply_token || '').trim();
const cmd = String($json.cmd || '').trim();
const headerColor = "#06C755";

const prices = [
  { label: "9,000 BTU", price: "700" },
  { label: "12,000 - 13,000 BTU", price: "800" },
  { label: "18,000 BTU", price: "900" },
  { label: "24,000 BTU", price: "1,000" },
];
const addons = [
  { item: "น้ำยาฆ่าเชื้อ (ล้างคอยล์)", price: "+100" },
  { item: "ระบบ Inverter", price: "+100" },
  { item: "ตรวจเช็ค/ประเมินหน้างาน", price: "1,000+", note: "กรณีเช็คแล้วไม่ซ่อม" },
];

const postbackAction = (label, data) => ({ type: "postback", label, data });

function genPriceFlex() {
  const priceRows = prices.map((p) => ({ type: "box", layout: "horizontal", contents: [{ type: "text", text: p.label, size: "sm", color: "#555555", flex: 3 }, { type: "text", text: `${p.price}.-`, size: "sm", color: "#111111", weight: "bold", align: "end", flex: 1 }], margin: "md" }));
  const addonRows = addons.flatMap((a) => { const mainRow = { type: "box", layout: "horizontal", contents: [{ type: "text", text: `🔧 ${a.item}`, size: "xs", color: "#666666", flex: 3, wrap: true }, { type: "text", text: a.price, size: "xs", color: "#ff334b", weight: "bold", align: "end", flex: 1, adjustMode: "shrink-to-fit" }], margin: "sm" }; if (!a.note) return [mainRow]; return [mainRow, { type: "text", text: a.note, size: "xxs", color: "#999999", margin: "xs", wrap: true }]; });
  return { type: "flex", altText: "ตารางราคาล้างแอร์ 2026", contents: { type: "bubble", size: "mega", header: { type: "box", layout: "vertical", backgroundColor: headerColor, paddingAll: "lg", contents: [{ type: "text", text: "❄️ ราคาล้างแอร์ติดผนัง", weight: "bold", color: "#ffffff", size: "lg" }, { type: "text", text: "อัปเดตปี 2026", color: "#ffffffcc", size: "xs", margin: "xs" }] }, body: { type: "box", layout: "vertical", contents: [{ type: "text", text: "ราคาเริ่มต้น (ล้างปกติ)", weight: "bold", size: "md", color: "#333333" }, { type: "separator", margin: "md", color: "#eeeeee" }, ...priceRows, { type: "separator", margin: "lg", color: "#eeeeee" }, { type: "box", layout: "vertical", margin: "lg", backgroundColor: "#f7f7f7", cornerRadius: "md", paddingAll: "md", contents: [{ type: "text", text: "📌 บริการเสริม & เงื่อนไข", size: "xs", weight: "bold", color: "#333333" }, ...addonRows, { type: "separator", margin: "md", color: "#e0e0e0" }, { type: "text", text: "🛡️ รับประกันน้ำหยดหลังล้าง 30 วัน", size: "xs", color: headerColor, weight: "bold", align: "center", margin: "md" }] }] }, footer: { type: "box", layout: "vertical", spacing: "sm", contents: [{ type: "button", style: "primary", color: headerColor, action: { type: "uri", label: "จองคิวทันที", uri: LIFF || "https://liff.line.me/2008445752-IZ9iXrPC" } }, { type: "button", style: "secondary", action: postbackAction("คุยกับแอดมิน", "MENU:TALK_ADMIN") }] } } };
}

function adminGateMenu() { return { type: "text", text: "เลือกหัวข้อติดต่อแอดมินครับ 👇", quickReply: { items: [{ type: "action", action: postbackAction("ติดตามงาน", "ADMIN:TRACK") }, { type: "action", action: postbackAction("แจ้งปัญหา", "ADMIN:ISSUE") }, { type: "action", action: postbackAction("อื่นๆ", "ADMIN:OTHER") }] } }; }
function adminAck(reason) { return { type: "text", text: `รับเรื่องแล้วครับ (${reason}) แอดมินจะติดต่อกลับให้เร็วที่สุด\nพิมพ์รายละเอียดเพิ่มได้เลย (ชื่อ/เบอร์/เลขงาน/ที่อยู่)` }; }
function bookMsg() { const link = LIFF || "https://liff.line.me/2008445752-IZ9iXrPC"; return { type: "text", text: `📅 จองคิวออนไลน์ได้ที่นี่ครับ\n${link}` }; }
function askAiIntro() { return { type: "text", text: "สวัสดีครับ 👋\nสอบถามเบื้องต้นได้เลย เช่น ราคา / พื้นที่บริการ / รับซ่อมไหม / ค่าตรวจเช็ค/ประเมินหน้างานเท่าไร\nค่าตรวจเช็ค/ประเมินหน้างาน เริ่มต้น 1,000 บาท กรณีเช็กแล้วไม่ซ่อม\nถ้าต้องการจองคิว ประเมินหน้างาน หรือตามงาน ผมจะส่งต่อแอดมินให้ครับ" }; }

let route = "IGNORE";
let replyPayload = null;
let pushPayload = null;

if (!replyToken) { return [{ json: { ...$json, route, replyPayload, pushPayload, cmd } }]; }

if (cmd === "MENU:PRICE_CLEAN") {
  route = "PRICE_SHOW";
  const announcementText = { type: "text", text: "📢 ประกาศแจ้งปรับราคาบริการล้างแอร์\nเนื่องจากต้นทุนในการเดินทางและการให้บริการปรับตัวสูงขึ้น ทางบริษัทขอแจ้งปรับราคาเริ่มต้นของบริการล้างแอร์ ดังนี้" };
  const followUpText = { type: "text", text: "หลังดูราคาแล้ว ถ้าต้องการสอบถามเบื้องต้น พิมพ์ถามได้เลย หรือกด “ติดต่อแอดมิน” ได้ทันทีค่ะ\nค่าตรวจเช็ค/ประเมินหน้างาน เริ่มต้น 1,000 บาท กรณีเช็คแล้วไม่ซ่อม" };
  replyPayload = { replyToken, messages: [announcementText, genPriceFlex(), followUpText] };
} else if (cmd === "MENU:BOOK") {
  route = "BOOK";
  replyPayload = { replyToken, messages: [bookMsg()] };
} else if (cmd === "MENU:ASK_AI") {
  route = "ASK_AI";
  replyPayload = { replyToken, messages: [askAiIntro()] };
} else if (cmd === "MENU:TALK_ADMIN") {
  route = "ADMIN_MENU";
  replyPayload = { replyToken, messages: [adminGateMenu()] };
} else {
  const m = cmd.match(/^ADMIN:(TRACK|ISSUE|OTHER)$/);
  if (m) {
    route = "ADMIN_PUSH";
    const reasonMap = { TRACK: "ติดตามงาน", ISSUE: "แจ้งปัญหา", OTHER: "อื่นๆ" };
    const reason = reasonMap[m[1]] || m[1];
    replyPayload = { replyToken, messages: [adminAck(reason)] };
    const adminTo = String($json.ADMIN_TO || "").trim();
    if (adminTo) {
      const who = String($json.line_user_id || $json.platform_user_id || "unknown");
      pushPayload = { to: adminTo, messages: [{ type: "text", text: `🔔 ลูกค้าขอคุยแอดมิน\nหัวข้อ: ${reason}\nผู้ใช้: ${who}\nOA: ${$json.account_key || "-"}\nเวลา: ${new Date().toLocaleString('th-TH')}` }] };
    }
  }
}

return [{ json: { ...$json, route, replyPayload, pushPayload, cmd } }];

const body = $json || {};
const orig = $('Normalize cmd').item.json;
const aiText = String(body.customer_reply || '').trim();
const hasReply = body.ok === true && !!aiText;

return [{ json: { ...orig, brain_response: body, aiText, hasReply } }];

const runtimeMode = String($json.RUNTIME_MODE || $json.runtime_mode || 'shadow').trim().toLowerCase();
const isLive = runtimeMode === 'live';
const isShadow = !isLive;
const platform = String($json.platform || $json.brain_payload?.channel || 'line').toLowerCase();
const aiText = String($json.aiText || $json.brain_response?.customer_reply || '').trim();

let replyPayload = null;
let fbReplyPayload = null;
let shouldSend = false;
let send_block_reason = null;

if (isLive && aiText) {
  if (platform === 'facebook') {
    const recipientId = String($json.fb_recipient_id || $json.platform_user_id || $json.line_user_id || '').trim();
    const pageToken = String($json.page_access_token || '').trim();

    if (recipientId && pageToken) {
      fbReplyPayload = {
        recipient: { id: recipientId },
        messaging_type: "RESPONSE",
        message: { text: aiText }
      };
      shouldSend = true;
    } else {
      send_block_reason = !recipientId ? 'missing_facebook_recipient_id' : 'missing_facebook_page_access_token';
    }
  } else {
    const replyToken = String($json.reply_token || '').trim();
    if (replyToken) {
      replyPayload = { replyToken, messages: [{ type: "text", text: aiText }] };
      shouldSend = true;
    } else {
      send_block_reason = 'missing_line_reply_token';
    }
  }
} else if (!aiText) {
  send_block_reason = 'missing_ai_text';
} else {
  send_block_reason = 'shadow_mode';
}

return [{
  json: {
    ...$json,
    replyPayload,
    fbReplyPayload,
    should_send_customer_reply: shouldSend,
    runtime_mode: runtimeMode,
    shadow_customer_reply_blocked: isShadow,
    send_block_reason
  }
}];

const runtimeMode = String($json.RUNTIME_MODE || 'shadow').trim().toLowerCase();
const brain = $json.brain_response || {};
const aiText = String($json.aiText || '').trim();
const intent = brain.intent || 'unknown';
const confidence = typeof brain.confidence === 'number' ? brain.confidence : null;
const missing = Array.isArray(brain.missing_fields) ? brain.missing_fields : [];
const userText = String($json.text || '').trim();

const lines = [
  runtimeMode === 'shadow' ? '🕶️ [SHADOW AI REVIEW]' : '🤖 [LIVE AI REVIEW]',
  `OA: ${String($json.account_key || '-')}`,
  `User: ${String($json.platform_user_id || $json.line_user_id || '-')}`,
  `Intent: ${intent}`,
  confidence === null ? 'Confidence: -' : `Confidence: ${confidence}`,
  '',
  'ลูกค้าพิมพ์:',
  userText || '-',
  '',
  'AI Draft:',
  aiText || '(no draft)'
];

if (brain.recommended_action) lines.push('', `Recommended: ${brain.recommended_action}`);
if (missing.length) lines.push(`Missing: ${missing.join(', ')}`);

return [{
  json: {
    account_key: $json.account_key,
    channel_platform_id: $json.channel_platform_id,
    platform_user_id: $json.platform_user_id || $json.line_user_id,
    event_type: 'shadow_ai_review',
    text: lines.join('\n'),
    cmd: null,
    reply_token: null,
    timestamp: Date.now(),
    raw: JSON.stringify({ runtime_mode: runtimeMode, customer_text: userText, ai_draft: aiText, brain_response: brain, source_event: $json.raw_event || null }),
    INBOX_BASE_URL: 'https://admin.paaair.online/webhook/line/chat'
  }
}];

const brain = $json.brain_response || {};
const runtimeMode = String($json.RUNTIME_MODE || $json.runtime_mode || 'shadow').trim().toLowerCase();
const nowIso = new Date().toISOString();
const accountKey = String($json.account_key || '');
const channelPlatformId = String($json.channel_platform_id || '');
const lineUserId = String($json.line_user_id || '');
const customerText = String($json.text || '').trim();
const aiDraft = String($json.aiText || brain.customer_reply || '').trim();
const missingFields = Array.isArray(brain.missing_fields) ? brain.missing_fields : [];
const extractedFields = brain.extracted_fields || {};
const metadata = brain.metadata || {};
const decisionMeta = brain.decision_meta || {};
const sourceEvent = $json.raw_event || null;
const ts = $json.ts || Date.now();

const reviewId = `SR-${ts}-${Math.random().toString(36).slice(2, 8)}`;
const caseKey = [accountKey, channelPlatformId, lineUserId].join('|');
const turnKey = [caseKey, ts].join('|');

return [{
  json: {
    review_id: reviewId,
    reviewed_at: nowIso,
    runtime_mode: runtimeMode,
    account_key: accountKey,
    channel_platform_id: channelPlatformId,
    line_user_id: lineUserId,
    case_key: caseKey,
    turn_key: turnKey,
    customer_text: customerText,
    active_flow_before: String(metadata.active_flow || ''),
    active_flow_after: String(metadata.active_flow_after || metadata.active_flow || ''),
    ai_intent: String(brain.intent || ''),
    ai_confidence: typeof brain.confidence === 'number' ? brain.confidence : '',
    ai_draft: aiDraft,
    recommended_action: String(brain.recommended_action || ''),
    should_handoff: brain.should_handoff === true ? 'true' : 'false',
    missing_fields: missingFields.join(', '),
    rule_hit: String(metadata.rule_hit || decisionMeta.rule_hit || ''),
    intercept_source: String(metadata.intercept_source || decisionMeta.intercept_source || ''),
    canonical_topic: String(metadata.canonical_topic || decisionMeta.canonical_topic || ''),
    handoff_state: String(metadata.handoff_state || ''),
    human_final_reply: '',
    review_label: '',
    is_correct: '',
    gap_score: '',
    bug_group: '',
    severity: '',
    fix_status: 'open',
    root_cause: '',
    promoted_to_rule: '',
    reviewer: '',
    note: '',
    brain_response_json: JSON.stringify(brain),
    raw_json: JSON.stringify(sourceEvent),
    extracted_fields_json: JSON.stringify(extractedFields),
    decision_meta_json: JSON.stringify(decisionMeta)
  }
}];

const input = $json || {};

const platform = String(input.platform || input.channel || 'line').trim().toLowerCase();
const channelUserId = String(input.channel_user_id || input.platform_user_id || input.line_user_id || input.sender_platform_id || input.raw_event?.sender?.id || input.raw_event?.source?.userId || '').trim();
const channelPlatformId = String(input.channel_platform_id || input.fb_page_id || input.page_id || input.raw_event?.recipient?.id || '').trim();
const accountKey = String(input.account_key || input.page_name || '').trim();
const text = String(input.text || input.content || input.message_text || input.raw_event?.message?.text || '').trim();
const messageId = input.platform_message_id || input.raw_event?.message?.mid || input.raw_event?.message?.id || input.message_id || null;
const messageType = input.message_type || input.raw_event?.message?.type || (text ? 'text' : 'unknown');
const timestamp = input.ts || input.timestamp || input.raw_event?.timestamp || Date.now();

let runtimeMode = String(input.RUNTIME_MODE || input.runtime_mode || 'shadow').trim().toLowerCase();
if (runtimeMode === 'active') runtimeMode = 'live';
if (!['shadow', 'live'].includes(runtimeMode)) runtimeMode = 'shadow';

const missing = [];
if (!platform) missing.push('channel');
if (!channelUserId) missing.push('channelUserId');
if (!channelPlatformId) missing.push('channelPlatformId');
if (!accountKey) missing.push('accountKey');
if (!text) missing.push('customerMessage');

return [{
  json: {
    ...input,
    platform,
    channel_platform_id: channelPlatformId,
    platform_user_id: channelUserId,
    line_user_id: input.line_user_id || channelUserId,
    RUNTIME_MODE: runtimeMode,
    schema_ok: missing.length === 0,
    schema_error: missing.length ? { missing } : null,
    brain_payload: {
      channel: platform,
      channelUserId,
      channelPlatformId,
      accountKey,
      threadId: null,
      customerMessage: text,
      sourceEvent: {
        replyToken: input.reply_token || null,
        messageId,
        messageType,
        timestamp,
        imageBase64: input.imageBase64 || null,
        mediaUrl: input.media_url || input.attachment_url || input.raw_event?.media_url || null
      },
      runtime: {
        requestId: `n8n_${platform}_main_${Date.now()}_${$execution.id}`,
        receivedAt: new Date().toISOString(),
        mode: `${platform}_text_inbound`,
        runtimeMode
      }
    }
  }
}];
